              "sub": "Auf Einladung von Kulturstaatsminister Wolfram Weimer haben sich heute die Kulturministerinnen und Kulturminister, die Kultursenatorinnen und Kultursenatoren der Länder und die Kommunalen Spitzenverbände zum 25. Kulturpolitischen Spitzengespräch in Berlin getroffen. Im Mittelpunkt standen die Bedeutung der Freiheit für Kunst und Kultur, die gemeinsame Verantwortung für eine offene demokratische Gesellschaft sowie die weitere Stärkung der Provenienzforschung. Der besondere Ort des Treffens, der Apollosaal der Staatsoper Unter den Linden Berlin, setzte zugleich den Rahmen: Die Kammerkonzerte im Apollosaal widmen sich in dieser Saison dem großen Thema „Freiheit“. Das Thema steht auch im Zusammenhang mit dem 2027 anstehenden Beethoven-Jahr, mit dem Deutschland an den 200. Todestag Ludwig van Beethovens erinnert. Gemeinsames Bekenntnis zur Freiheit der Kunst Zum Auftakt des Kulturpolitischen Spitzengesprächs bekräftigten Bund, Länder und Kommunen das rechtliche und politische Fundamen..."
