              "sub": "Staatsminister Weimer hat den Anselm-Kiefer-Pavillon am Museum Würth in Künzelsau eröffnet. Damit wird erstmals das großformatige Werk „Schwarze Flocken“ von Anselm Kiefer öffentlich zugänglich und bekommt einen dauerhaften Ausstellungsort. Es gehört zu den bedeutendsten Werken der Sammlung Würth. Der eigens für das Werk entworfene Pavillon stammt vom international renommierten Architekten David Chipperfield. Am 13. Oktober 2026 öffnet der Pavillon seine Tore für Besucherinnen und Besucher. Kulturstaatsminister Weimer erklärt dazu: „Anselm Kiefers monumentale Kunst zeigt, wie sehr die Geschichte in unsere Gegenwart hineinwirkt. Sie lässt uns nicht vergessen und fordert uns auf, genau hinzusehen. Mit ‚Schwarze Flocken‘ wird ein herausragendes Werk seines Schaffens erstmals für die Öffentlichkeit erlebbar. David Chipperfield verleiht diesem Werk mit seiner Architektur eine eindrucksvolle Wirkung. Die Eröffnung des Kiefer-Pavillons ist ein echter Gewinn für die kulturelle Landschaft i..."
